using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Shares the phone number of the current user with a mutual contact. Supposed to be called when the user clicks on chatActionBarSharePhoneNumber
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SharePhoneNumberAsync(long userId = default)
    {

           using var activity =  StartCallActivity("SharePhoneNumberAsync", typeof(SharePhoneNumber).FullName ?? "SharePhoneNumberAsync");

           try
           {
             return client.SharePhoneNumberAsync(userId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
// REUSE-IgnoreEnd